    assert skyramp.get_response_value(endpoint_2_POST_response, "name") == flow_name

    # Request Body
    endpoint_1_POST_request_body = r'''{
        "flow_id": "9a3f7e21-8b45-4d16-a2c9-7e5b1f4d8c30",
        "state": {
            "type": "SCHEDULED"
        },
        "work_pool_name": "default-agent-pool",
        "work_queue_name": "sk-byname-queue"
    }'''

